"""Fetch every order page and every referenced customer once, with retries; save raw data for the compute step.

Usage: python3 -I fetch.py OUT_DIR
"""
import email.utils
import json
import os
import sys
import time
import urllib.error
import urllib.request

BASE = "http://localhost:8080"
MAX_ATTEMPTS = 60


class FetchError(RuntimeError):
    pass


class Client:
    def __init__(self, log_path):
        self.token = None
        self.log_path = log_path
        self.stats = {"requests": 0, "token_fetches": 0, "status": {}}

    def _raw(self, method, path, auth):
        req = urllib.request.Request(BASE + path, method=method)
        if auth:
            req.add_header("Authorization", "Bearer " + self.token)
        t0 = time.time()
        try:
            with urllib.request.urlopen(req, timeout=30) as r:
                status, headers, body = r.status, dict(r.headers.items()), r.read()
        except urllib.error.HTTPError as e:
            status, headers, body = e.code, dict(e.headers.items()), e.read()
        except Exception as e:  # connection reset, timeout, etc.
            status, headers, body = None, {}, repr(e).encode()
        self.stats["requests"] += 1
        self.stats["status"][str(status)] = self.stats["status"].get(str(status), 0) + 1
        with open(self.log_path, "a") as f:
            f.write(json.dumps({"t": t0, "method": method, "path": path,
                                "token": self.token if auth else None, "status": status,
                                "headers": headers, "body": body.decode("utf-8", "replace")}) + "\n")
        return status, headers, body

    def _retry_after(self, headers, body):
        """Seconds the server asked us to wait (largest of header and body hints)."""
        waits = []
        h = headers.get("Retry-After")
        if h is not None:
            try:
                waits.append(float(h))
            except ValueError:
                dt = email.utils.parsedate_to_datetime(h)
                waits.append(dt.timestamp() - time.time())
        try:
            b = json.loads(body)
            if isinstance(b, dict) and b.get("retry_after") is not None:
                waits.append(float(b["retry_after"]))
        except ValueError:
            pass
        if not waits:
            raise FetchError(f"429 without a wait hint: headers={headers} body={body[:200]!r}")
        return max(0.0, max(waits))

    def refresh_token(self):
        for attempt in range(MAX_ATTEMPTS):
            status, headers, body = self._raw("POST", "/token", auth=False)
            if status == 200:
                tok = json.loads(body).get("token")
                if tok:
                    self.token = tok
                    self.stats["token_fetches"] += 1
                    return
            if status == 429:
                time.sleep(self._retry_after(headers, body) + 0.05)
                continue
            time.sleep(min(0.25 * (attempt + 1), 3))
        raise FetchError("could not obtain a token")

    def get_json(self, path, allow_404=False):
        if self.token is None:
            self.refresh_token()
        fresh_401s = 0
        for attempt in range(MAX_ATTEMPTS):
            status, headers, body = self._raw("GET", path, auth=True)
            if status == 200:
                try:
                    return json.loads(body)
                except ValueError:
                    time.sleep(0.2)  # truncated/garbled body: ask again
                    continue
            if status == 401:
                fresh_401s += 1
                if fresh_401s > 5:
                    raise FetchError(f"repeated 401 on {path}: {body[:200]!r}")
                self.refresh_token()
                continue
            if status == 429:
                time.sleep(self._retry_after(headers, body) + 0.05)
                continue
            if status == 404 and allow_404:
                return None
            if status is None or status >= 500:
                time.sleep(min(0.25 * (attempt + 1), 3))
                continue
            raise FetchError(f"unexpected {status} on {path}: headers={headers} body={body[:300]!r}")
        raise FetchError(f"gave up on {path} after {MAX_ATTEMPTS} attempts")


def main(out_dir):
    os.makedirs(out_dir, exist_ok=True)
    c = Client(os.path.join(out_dir, "http_log.jsonl"))

    # Orders: follow "next" from page 1; check the page sequence and total_pages are consistent.
    pages = []
    path = "/orders?page=1"
    expected_page = 1
    total_pages = None
    while path:
        d = c.get_json(path)
        if d.get("page") != expected_page:
            raise FetchError(f"asked for page {expected_page} via {path}, got page {d.get('page')}")
        if total_pages is None:
            total_pages = d["total_pages"]
        elif d["total_pages"] != total_pages:
            raise FetchError(f"total_pages changed {total_pages} -> {d['total_pages']} at page {expected_page}")
        if not isinstance(d.get("items"), list):
            raise FetchError(f"page {expected_page} has no items list")
        pages.append(d)
        path = d.get("next")
        if path is not None and path != f"/orders?page={expected_page + 1}":
            print(f"note: page {expected_page} next={path!r}", file=sys.stderr)
        expected_page += 1
    if len(pages) != total_pages:
        raise FetchError(f"fetched {len(pages)} pages but total_pages={total_pages}")

    # Customers: each distinct id once, cached.
    cust_ids = sorted({it["customer_id"] for d in pages for it in d["items"]})
    customers = {}
    for cid in cust_ids:
        rec = c.get_json(f"/customers/{cid}", allow_404=True)
        if rec is None:
            # Confirm a 404 is stable before treating the id as unknown.
            rec = c.get_json(f"/customers/{cid}", allow_404=True)
        if rec is not None and rec.get("id") != cid:
            raise FetchError(f"asked for customer {cid}, got record for {rec.get('id')!r}")
        customers[cid] = rec

    with open(os.path.join(out_dir, "order_pages.json"), "w") as f:
        json.dump(pages, f)
    with open(os.path.join(out_dir, "customers.json"), "w") as f:
        json.dump(customers, f, indent=1, sort_keys=True)
    print(json.dumps({"pages": len(pages), "listings": sum(len(d["items"]) for d in pages),
                      "customers": len(customers),
                      "customers_404": sorted(k for k, v in customers.items() if v is None),
                      **c.stats}, indent=1))


if __name__ == "__main__":
    main(sys.argv[1])

