        raise FetchError(f"gave up on {path} after {MAX_ATTEMPTS} attempts")


def main(out_dir):
    os.makedirs(out_dir, exist_ok=True)
    c = Client(os.path.join(out_dir, "http_log.jsonl"))

    # Orders: follow "next" from page 1; check the page sequence and total_pages are consistent.
    pages = []
    path = "/orders?page=1"
    expected_page = 1
    total_pages = None
    while path:
        d = c.get_json(path)
        if d.get("page") != expected_page:
            raise FetchError(f"asked for page {expected_page} via {path}, got page {d.get('page')}")
        if total_pages is None:
            total_pages = d["total_pages"]
        elif d["total_pages"] != total_pages:
            raise FetchError(f"total_pages changed {total_pages} -> {d['total_pages']} at page {expected_page}")
        if not isinstance(d.get("items"), list):
            raise FetchError(f"page {expected_page} has no items list")
        pages.append(d)
        path = d.get("next")
        if path is not None and path != f"/orders?page={expected_page + 1}":
            print(f"note: page {expected_page} next={path!r}", file=sys.stderr)
        expected_page += 1
    if len(pages) != total_pages:
        raise FetchError(f"fetched {len(pages)} pages but total_pages={total_pages}")

    # Customers: each distinct id once, cached.
    cust_ids = sorted({it["customer_id"] for d in pages for it in d["items"]})
    customers = {}
    for cid in cust_ids:
        rec = c.get_json(f"/customers/{cid}", allow_404=True)
        if rec is None:
            # Confirm a 404 is stable before treating the id as unknown.
            rec = c.get_json(f"/customers/{cid}", allow_404=True)
        if rec is not None and rec.get("id") != cid:
            raise FetchError(f"asked for customer {cid}, got record for {rec.get('id')!r}")
        customers[cid] = rec

    with open(os.path.join(out_dir, "order_pages.json"), "w") as f:
        json.dump(pages, f)
    with open(os.path.join(out_dir, "customers.json"), "w") as f:
        json.dump(customers, f, indent=1, sort_keys=True)
    print(json.dumps({"pages": len(pages), "listings": sum(len(d["items"]) for d in pages),
                      "customers": len(customers),
                      "customers_404": sorted(k for k, v in customers.items() if v is None),
                      **c.stats}, indent=1))


if __name__ == "__main__":
    main(sys.argv[1])

